from __future__ import annotations

from pydantic import Field
from typing_extensions import TypedDict

from ..core import SdkBaseModel


class SendTaskHeartbeatInput(SdkBaseModel):
    task_token: str = Field(alias="taskToken")
    """The token that represents this task. Task tokens are generated by Step Functions when tasks are assigned to a
    worker, or in the context object when a workflow enters a task state. See GetActivityTaskOutput$taskToken."""


class SendTaskHeartbeatInputDict(TypedDict):
    task_token: str
